1	/**
2	 * ABI contract between the orchestrator and any executor.
3	 *
4	 * The orchestrator serialises ExecutorInput into env vars before spawning
5	 * the executor process. The executor writes an ExecutorResult to the path
6	 * at resultPath. The orchestrator reads and validates that file on exit.
7	 */
8	
9	export interface ExecutorInput {
10	  taskId: string;
11	  featureId: string;
12	  workspaceId: string;
13	  /** Git URL of the implementation repo (SSH or HTTPS). */
14	  taskRepoUrl: string;
15	  /** Feature branch the executor must check out and push to. */
16	  taskRepoBranch: string;
17	  /**
18	   * Working-directory path. The **executor** materializes the repo here:
19	   * if the path already exists with `origin` matching `taskRepoUrl`,
20	   * fetch + checkout + pull; otherwise clone fresh from `taskRepoUrl`.
21	   * The orchestrator may pre-populate this path as an optimization in
22	   * shared-filesystem topologies, but it is not required to.
23	   */
24	  taskRepoPath: string;
25	  /** Path to the markdown briefing file written by the orchestrator. */
26	  briefingPath: string;
27	  /** Path the executor must write result.json to. */
28	  resultPath: string;
29	  /** Optional token budget; absent for non-LLM executors. */
30	  budgetTokens?: number;
31	  sshKeyPath: string;
32	  githubToken: string;
33	}
34	
35	export type TerminalStatus = "in_review" | "blocked" | "failed";
36	
37	export interface ExecutorResult {
38	  terminal_status: TerminalStatus;
39	  token_usage?: { input: number; output: number };
40	  /** Required when terminal_status === "blocked". */
41	  blocked_reason?: string;
42	  /** Required when terminal_status === "blocked". */
43	  blocked_suggestion?: string;
44	}
45	
46	/**
47	 * The orchestrator-side seam every executor must satisfy.
48	 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
49	 */
50	export interface ExecutorAdapter {
51	  run(input: ExecutorInput): Promise<ExecutorResult>;
52	}
