1	import { Ajv } from "ajv";
2	import type { ErrorObject } from "ajv";
3	import type { ExecutorResult } from "./types.js";
4	
5	const ajv = new Ajv({ allErrors: true });
6	
7	export const resultJsonSchema = {
8	  $schema: "http://json-schema.org/draft-07/schema#",
9	  title: "ExecutorResult",
10	  description: "The JSON payload an executor writes to resultPath on completion.",
11	  type: "object",
12	  required: ["terminal_status"],
13	  additionalProperties: false,
14	  properties: {
15	    terminal_status: {
16	      type: "string",
17	      enum: ["in_review", "blocked", "failed"],
18	    },
19	    token_usage: {
20	      type: "object",
21	      required: ["input", "output"],
22	      additionalProperties: false,
23	      properties: {
24	        input: { type: "integer", minimum: 0 },
25	        output: { type: "integer", minimum: 0 },
26	      },
27	    },
28	    blocked_reason: { type: "string", minLength: 1 },
29	    blocked_suggestion: { type: "string", minLength: 1 },
30	  },
31	  if: {
32	    properties: { terminal_status: { const: "blocked" } },
33	    required: ["terminal_status"],
34	  },
35	  then: {
36	    required: ["terminal_status", "blocked_reason"],
37	  },
38	} as const;
39	
40	const _validateFn = ajv.compile(resultJsonSchema);
41	
42	export interface ValidationError {
43	  message: string;
44	  path: string;
45	}
46	
47	export interface ValidationResult {
48	  valid: boolean;
49	  errors: ValidationError[];
50	}
51	
52	/**
53	 * Validate an executor result.json payload against the ABI schema.
54	 * Schema violations must be mapped by the orchestrator to
55	 * terminal_status: "failed", blocked_reason: "result_schema_invalid".
56	 */
57	export function validateResult(data: unknown): ValidationResult {
58	  const valid = _validateFn(data);
59	  if (valid) {
60	    return { valid: true, errors: [] };
61	  }
62	  const errors: ValidationError[] = (_validateFn.errors ?? []).map(
63	    (e: ErrorObject) => ({
64	      message: e.message ?? "unknown validation error",
65	      path: e.instancePath || "/",
66	    }),
67	  );
68	  return { valid: false, errors };
69	}
70	
71	/**
72	 * Type guard: returns true and narrows data to ExecutorResult when the
73	 * schema validates.
74	 */
75	export function isValidResult(data: unknown): data is ExecutorResult {
76	  return validateResult(data).valid;
77	}
