1	import type { ExecutorAdapter, ExecutorInput, ExecutorResult } from "./types.js";
2	
3	/**
4	 * A no-I/O ExecutorAdapter used by orchestrator tests.
5	 * The factory accepts a fixed result (or a factory function) and returns
6	 * an adapter that resolves immediately with that result — no spawning,
7	 * no file I/O, no side effects.
8	 */
9	export function createFakeAdapter(
10	  result: ExecutorResult | (() => ExecutorResult),
11	): ExecutorAdapter {
12	  return {
13	    async run(_input: ExecutorInput): Promise<ExecutorResult> {
14	      return typeof result === "function" ? result() : result;
15	    },
16	  };
17	}
18	
19	/**
20	 * Convenience: a FakeAdapter that always reports in_review.
21	 */
22	export function createInReviewAdapter(): ExecutorAdapter {
23	  return createFakeAdapter({ terminal_status: "in_review" });
24	}
25	
26	/**
27	 * Convenience: a FakeAdapter that always reports blocked.
28	 */
29	export function createBlockedAdapter(
30	  blocked_reason: string,
31	  blocked_suggestion?: string,
32	): ExecutorAdapter {
33	  return createFakeAdapter({
34	    terminal_status: "blocked",
35	    blocked_reason,
36	    blocked_suggestion,
37	  });
38	}
39	
40	/**
41	 * Convenience: a FakeAdapter that always reports failed.
42	 */
43	export function createFailedAdapter(): ExecutorAdapter {
44	  return createFakeAdapter({ terminal_status: "failed" });
45	}
