18	
19	  it("accepts a valid blocked result with reason and suggestion", () => {
20	    const result = validateResult({
21	      terminal_status: "blocked",
22	      blocked_reason: "missing_tool",
23	      blocked_suggestion: "Install the required tool and retry.",
24	    });
25	    expect(result.valid).toBe(true);
26	  });
27	
28	  it("accepts a valid blocked result with reason and without suggestion", () => {
29	    const result = validateResult({
30	      terminal_status: "blocked",
31	      blocked_reason: "missing_tool",
32	    });
33	    expect(result.valid).toBe(true);
34	  });
35	
36	  it("accepts a valid failed result", () => {
37	    const result = validateResult({ terminal_status: "failed" });
38	    expect(result.valid).toBe(true);
39	  });
40	
41	  it("rejects a blocked result missing blocked_reason", () => {
42	    const result = validateResult({ terminal_status: "blocked" });
43	    expect(result.valid).toBe(false);
44	    expect(result.errors.length).toBeGreaterThan(0);
45	  });
46	
47	  it("rejects an unknown terminal_status", () => {
48	    const result = validateResult({ terminal_status: "unknown_value" });
49	    expect(result.valid).toBe(false);
50	    expect(result.errors.length).toBeGreaterThan(0);
51	  });
52	
53	  it("rejects a result with missing terminal_status", () => {
54	    const result = validateResult({});
55	    expect(result.valid).toBe(false);
56	    expect(result.errors.length).toBeGreaterThan(0);
57	  });
58	
59	  it("rejects a result with additional unknown properties", () => {
60	    const result = validateResult({
61	      terminal_status: "in_review",
62	      unexpected_field: "oops",
