68	describe("isValidResult", () => {
69	  it("returns true for a valid in_review result and narrows the type", () => {
70	    const data: unknown = { terminal_status: "in_review" };
71	    expect(isValidResult(data)).toBe(true);
72	    if (isValidResult(data)) {
73	      expect(data.terminal_status).toBe("in_review");
74	    }
75	  });
76	
77	  it("returns false for an invalid result", () => {
78	    expect(isValidResult({ terminal_status: "blocked" })).toBe(false);
79	  });
