553	// ── Log flush (best-effort) ───────────────────────────────────────────────────
554	
555	function flushLog(
556	  workspaceRoot: string,
557	  featureId: string,
558	  taskId: string,
559	  taskBranch: string,
560	  runStartIso: string,
561	  gitAuthorEmail: string,
562	  gitAuthorName: string,
563	  stdout: string,
564	  outcome: string,
565	  sshKeyPath: string | undefined,
566	): void {
567	  try {
568	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
569	    mkdirSync(logsDir, { recursive: true });
570	
571	    const safeIso = runStartIso.replace(/[:.]/g, "-");
572	    const logFilename = `${safeIso}.jsonl`;
573	    const logPath = join(logsDir, logFilename);
574	
575	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
576	    if (stdout) {
577	      appendFileSync(logPath, stdout.endsWith("\n") ? stdout : stdout + "\n");
578	    }
579	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
580	
581	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
582	    const env = {
583	      ...process.env,
584	      GIT_AUTHOR_NAME: gitAuthorName,
585	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
586	      GIT_COMMITTER_NAME: gitAuthorName,
587	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
588	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
589	    };
590	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
591	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
592	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
593	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
594	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
595	  } catch { /* best-effort */ }
596	}
597	
598	main().catch((e) => {
599	  try {
600	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
601	  } catch { /* last resort */ }
602	  process.exit(1);
603	});
