195	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
196	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
197	  } catch (e) {
198	    emit({ type: "fatal_missing_env", details: (e as Error).message });
199	    return 4;
200	  }
