202	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
203	
204	  const sshResolution = resolveSSHKey(process.env);
205	  const sshKeyPath = sshResolution.sshKeyPath;
206	  if (sshResolution.warned) {
207	    emit({ type: "warn_no_ssh_key", note: "Neither SSH_PRIVATE_KEY nor SSH_KEY_PATH is set." });
208	  }
209	
210	  const bootstrapResult = await runBootstrap({
211	    agentYamlPath,
212	    workflowLocalPath,
213	    workflowUrl: process.env.WORKFLOW_URL,
214	    workspacesRoot,
215	    sshKeyPath,
216	  });
217	
218	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
219	
220	  const config = bootstrapResult.config!;
221	  const githubToken = process.env.GITHUB_TOKEN ?? "";
222	  if (!githubToken) emit({ type: "warn_no_github_token" });
223	
224	  let lastPrPollAt: number | null = null;
