226	  async function runOneCycle(): Promise<CycleOutcome> {
227	    const pullResults = pullWorkspaces({
228	      watchUrls: config.watches,
229	      sshKeyPath,
230	      workspacesRoot,
231	      workflowUrl: process.env.WORKFLOW_URL,
232	      workflowLocalPath,
233	      emit,
234	    });
235	
236	    const haltedUrls = new Set(
237	      pullResults
238	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
239	        .map((r) => r.url),
240	    );
241	
242	    let outcome: CycleOutcome = "idle";
243	    const pulledWorkspaceRoots: string[] = [];
244	
245	    outerLoop:
246	    for (const watchUrl of config.watches) {
247	      if (haltedUrls.has(watchUrl)) continue;
248	
249	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
250	      pulledWorkspaceRoots.push(workspaceLocalPath);
251	
252	      if (!existsSync(workspaceLocalPath)) {
253	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
254	        continue;
255	      }
256	
257	      let eligibleTasks;
258	      try {
259	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
260	      } catch (e) {
261	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
262	        continue;
263	      }
264	
265	      if (eligibleTasks.length === 0) {
266	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
267	        continue;
268	      }
269	
270	      for (const { task, featureId } of eligibleTasks) {
271	        const claimResult = await claimTask({
272	          workspaceRoot: workspaceLocalPath,
273	          taskId: task.id,
274	          featureId,
275	          gitAuthorEmail,
276	          gitAuthorName,
277	          sshKeyPath,
278	          jitterMaxSeconds: config.jitter_max_seconds,
279	        });
280	
281	        const taskBranch = taskBranchName(featureId, task.id);
282	
283	        if (!claimResult.won) {
284	          if (claimResult.reason !== "branch_blocked_recovery") {
285	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
286	            continue;
287	          }
288	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
289	        } else {
290	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
291	        }
292	
293	        // ── Open management-repo PR ───────────────────────────────────────────
294	        if (githubToken) {
295	          try {
296	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
297	            await openWorkspacePr({
298	              workspaceRoot: workspaceLocalPath,
299	              featureId,
300	              taskId: task.id,
301	              branch: taskBranch,
302	              baseBranch: mgmtCoords.baseBranch,
303	              githubToken,
304	              repoOwner: mgmtCoords.owner,
305	              repoName: mgmtCoords.repo,
306	              gitAuthorEmail,
307	              gitAuthorName,
308	              sshKeyPath,
309	            });
310	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
311	          } catch (e) {
312	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
313	          }
314	        }
315	
316	        // ── Resolve model + task repo ────────────────────────────────────────
317	        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
318	        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
319	        const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
320	        const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
321	
322	        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
323	        let taskModelOverrides = {};
324	        try {
325	          taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
326	        } catch { /* non-fatal */ }
327	
328	        const implementationModel = resolveModel(
329	          workspaceModelPolicy,
330	          taskModelOverrides,
331	          "implementation",
332	          task.id,
333	        );
334	
335	        // ── RAG pre-flight ───────────────────────────────────────────────────
336	        const mcpRagUrl = process.env.MCP_RAG_URL;
337	        const workspaceYaml = parseYaml(
338	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
339	        ) as { workspace_id: string };
340	        const ragQuery = `${task.title} ${featureId}`;
341	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
342	
343	        try {
344	          writeRagPreFlight(
345	            workspaceLocalPath,
346	            featureId,
347	            task.id,
348	            taskBranch,
349	            gitAuthorEmail,
350	            sshKeyPath,
351	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
352	          );
353	        } catch (e) {
354	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details: String(e) });
355	          continue;
356	        }
357	
358	        // ── Generate briefing ────────────────────────────────────────────────
359	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
360	        const baseContext = generateBriefing({
361	          taskId: task.id,
362	          featureId,
363	          taskTitle: task.title,
364	          taskBranch,
365	          taskRepo: task.repo,
366	          taskRepoRoot,
367	          workspaceRoot: workspaceLocalPath,
368	          gitAuthorEmail,
369	          gitAuthorName,
370	          implementationModel,
371	          resultPath,
372	        });
373	        const briefingContent = ragPreFlight.block
374	          ? `${baseContext}\n\n${ragPreFlight.block}`
375	          : baseContext;
376	
377	        const briefingDir = join(tmpdir(), `briefing-${task.id}`);
378	        mkdirSync(briefingDir, { recursive: true });
