380	        writeFileSync(briefingPath, briefingContent, "utf-8");
381	
382	        // ── Build ExecutorInput ──────────────────────────────────────────────
383	        const input: ExecutorInput = {
384	          taskId: task.id,
385	          featureId,
386	          workspaceId: workspaceYaml.workspace_id,
387	          taskRepoUrl,
388	          taskRepoBranch: taskBranch,
389	          taskRepoPath: taskRepoRoot,
390	          briefingPath,
391	          resultPath,
392	          budgetTokens: config.budget.max_tokens_per_task,
393	          sshKeyPath: sshKeyPath ?? "",
394	          githubToken,
395	        };
396	
397	        // ── Run executor ─────────────────────────────────────────────────────
398	        const perTaskAdapter = new SubProcessAdapter({
399	          extraEnv: {
