406	            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
407	            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
408	            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
409	              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
410	              : {}),
411	          },
412	        });
413	
414	        const execResult = await perTaskAdapter.run(input);
415	
416	        emit({
417	          type: "executor_result",
418	          task_id: task.id,
