444	          const mutateErr = mutateTaskYaml({
445	            workspaceRoot: workspaceLocalPath,
446	            featureId,
447	            taskId: task.id,
448	            taskBranch,
449	            result: execResult,
450	            prUrl,
451	            gitAuthorEmail,
452	            gitAuthorName,
453	            sshKeyPath,
454	          });
455	          if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
456	
457	          const logErr = appendLogEntry({
458	            workspaceRoot: workspaceLocalPath,
459	            featureId,
460	            taskId: task.id,
461	            taskBranch,
462	            entry: {
463	              action: "in_review",
464	              by: gitAuthorEmail,
465	              note: prUrl ? `Implementation PR opened: ${prUrl}` : "Implementation complete.",
466	            },
467	            gitAuthorEmail,
468	            gitAuthorName,
469	            sshKeyPath,
470	          });
471	          if (logErr) emit({ type: "append_log_failed", task_id: task.id, details: logErr });
472	        } else {
473	          const mutateErr = mutateTaskYaml({
474	            workspaceRoot: workspaceLocalPath,
475	            featureId,
476	            taskId: task.id,
477	            taskBranch,
478	            result: execResult,
479	            gitAuthorEmail,
480	            gitAuthorName,
481	            sshKeyPath,
482	          });
483	          if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
484	
485	          const logErr = appendLogEntry({
486	            workspaceRoot: workspaceLocalPath,
487	            featureId,
488	            taskId: task.id,
489	            taskBranch,
490	            entry: {
491	              action: "blocked",
492	              by: gitAuthorEmail,
493	              note: execResult.blocked_reason ?? "executor returned non-in_review status",
494	            },
495	            gitAuthorEmail,
496	            gitAuthorName,
497	            sshKeyPath,
498	          });
499	          if (logErr) emit({ type: "append_log_failed", task_id: task.id, details: logErr });
500	        }
501	
502	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: execResult.terminal_status });
503	        outcome = "ran_task";
504	        break outerLoop;
505	      }
506	    }
507	
508	    // ── In-review PR poll ─────────────────────────────────────────────────────
509	    if (githubToken) {
510	      const prPollIntervalMs =
511	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
512	      const now = Date.now();
513	
514	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
515	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
516	        try {
517	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
518	            workspaceRoots: pulledWorkspaceRoots,
519	            githubToken,
520	            emit,
521	          });
522	
523	          for (const wsRoot of pulledWorkspaceRoots) {
524	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
525	            if (wsResults.some((r) => r.mergeable === false)) {
526	              await handleMergeConflicts({
527	                prResults: wsResults,
528	                workspaceRoot: wsRoot,
529	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
530	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
531	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
532	                gitAuthorEmail,
533	                gitAuthorName,
534	                sshKeyPath,
535	                emit,
536	              });
537	            }
538	          }
539	
540	          for (const wsRoot of pulledWorkspaceRoots) {
541	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
542	            if (wsResults.some((r) => r.hasOpenComments === true)) {
543	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
544	              await handleDraftReviews({
545	                prResults: wsResults,
546	                workspaceRoot: wsRoot,
547	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
548	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
549	                resolveImplementationModel: (fId, tId) => {
550	                  try {
551	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
552	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
553	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
554	                  } catch {
