556	                  }
557	                },
558	                gitAuthorEmail,
559	                gitAuthorName,
560	                sshKeyPath,
561	                workflowLocalPath,
562	                maxTurns: config.budget.max_iterations,
563	                maxTokens: config.budget.max_tokens_per_task,
564	                logSinkEnabled: config.log_sink.enabled,
565	                workspaceId: (() => {
566	                  try {
567	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
568	                  } catch { return ""; }
569	                })(),
570	                githubToken,
571	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
572	                emit,
573	              });
574	            }
575	          }
576	
577	          for (const wsRoot of pulledWorkspaceRoots) {
578	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
579	            if (wsResults.some((r) => r.merged === true)) {
580	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
