582	                prResults: wsResults,
583	                workspaceRoot: wsRoot,
584	                mgmtRepoOwner: mgmtCoords.owner,
585	                mgmtRepoName: mgmtCoords.repo,
586	                mgmtBaseBranch: mgmtCoords.baseBranch,
587	                githubToken,
588	                gitAuthorEmail,
589	                gitAuthorName,
590	                sshKeyPath,
591	                emit,
592	              });
593	            }
594	          }
595	
596	          for (const wsRoot of pulledWorkspaceRoots) {
597	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
598	            if (wsRecoveries.length > 0) {
599	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
