1	/**
2	 * Agent activation loop.
3	 *
4	 * Drives the scan → claim → run cycle on a configurable interval.
5	 * All real I/O (sleep, the cycle itself) is injectable so tests can run
6	 * synchronously with recorded side-effects.
7	 *
8	 * Behaviour controlled by idle_sleep_seconds:
9	 *   0   → single-shot mode: run one cycle and return.
10	 *         Suitable for external schedulers (K8s CronJob, systemd timer).
11	 *   >0  → continuous mode: run cycles indefinitely, sleeping between them.
12	 *         Sleep is applied after every cycle — whether the cycle ran a task
13	 *         or found nothing (idle).
14	 */
15	
16	import type { AgentConfig } from "../config/validate-agent-yaml.js";
17	
18	/** Result returned by one activation cycle. */
19	export type CycleOutcome = "ran_task" | "idle";
20	
21	export interface AgentLoopOptions {
22	  config: AgentConfig;
23	  /** Execute one activation cycle. Must never throw — catch and return "idle" on error. */
24	  runCycle: () => Promise<CycleOutcome>;
25	  emit: (event: Record<string, unknown>) => void;
26	  /** Pause execution for ms milliseconds. Default: setTimeout-based. Injectable for tests. */
27	  sleep?: (ms: number) => Promise<void>;
28	}
29	
30	const defaultSleep = (ms: number): Promise<void> =>
31	  new Promise((resolve) => setTimeout(resolve, ms));
32	
33	/**
34	 * Run the agent activation loop.
35	 *
36	 * Returns only when:
37	 *   - single-shot mode (idle_sleep_seconds === 0): after one cycle.
38	 *   - In continuous mode: never (infinite loop — caller is responsible for
39	 *     process lifecycle).
40	 */
41	export async function runAgentLoop(opts: AgentLoopOptions): Promise<void> {
42	  const { config, runCycle, emit, sleep = defaultSleep } = opts;
43	  const sleepMs = (config.idle_sleep_seconds ?? 60) * 1000;
44	
45	  if (sleepMs === 0) {
46	    // Single-shot mode: one cycle, then return so main() can exit(0).
47	    await runCycle();
48	    return;
49	  }
50	
51	  // Continuous mode: cycle indefinitely with inter-cycle sleep.
52	  while (true) {
53	    const outcome = await runCycle();
54	
55	    if (outcome === "idle") {
56	      emit({ type: "activation_idle", sleep_ms: sleepMs });
57	    } else {
58	      emit({ type: "activation_complete", sleep_ms: sleepMs });
59	    }
60	
61	    await sleep(sleepMs);
62	  }
63	}
