1	/**
2	 * T7/T2: Git-based claim protocol with task-branch creation and SHA contention detection.
3	 *
4	 * The orchestrator creates feature/<featureId>-<taskId> before committing the claim.
5	 * The management repo is on the task branch from the moment the claim succeeds.
6	 *
7	 * Contention resolution is SHA-based, not identity-based:
8	 *   - Competing agents create the task branch from the same main HEAD and race to push.
9	 *   - First push wins (fast-forward). Loser gets a non-fast-forward rejection, fetches,
10	 *     and compares SHA with origin/<taskBranch>.
11	 *   - SHA match  → this agent's commit landed (rebase re-ordered the push) → won.
12	 *   - SHA differ → another agent's commit is on remote HEAD → lost.
13	 *
14	 * Branch-already-exists handling (re-claim or blocked recovery):
15	 *   - blocked_context null:  interrupted prior claim — checkout + reset to origin/<branch>.
16	 *   - blocked_context non-null: blocked recovery path — return branch_blocked_recovery.
17	 *
18	 * Pre-commit jitter (50–500 ms, bounded by jitter_max_seconds) de-synchronises agents
19	 * that pull from the same cron tick and reduces the collision rate.
20	 */
21	
22	import { execSync, spawnSync } from "node:child_process";
23	import { readFileSync, writeFileSync } from "node:fs";
24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
25	import type { Task } from "../types/task.js";
26	import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
27	import { buildGitCommitEnv } from "../git-env.js";
28	
29	// ── Public types ──────────────────────────────────────────────────────────────
30	
31	export interface ClaimTaskOptions {
32	  /** Absolute path to the management (workspace) repo root. */
33	  workspaceRoot: string;
34	  /** Task ID to claim (e.g. "T7"). */
35	  taskId: string;
36	  /** Feature directory ID (e.g. "task-branch-lifecycle"). */
37	  featureId: string;
38	  /**
39	   * GIT_AUTHOR_EMAIL for the claim commit.
40	   * Sourced from the resolved environment by the caller — not read from process.env
41	   * directly so the protocol is testable with arbitrary identities.
42	   */
43	  gitAuthorEmail: string;
44	  /** GIT_AUTHOR_NAME for the claim commit. Defaults to gitAuthorEmail if omitted. */
45	  gitAuthorName?: string;
46	  /** SSH private key path for git push. Omit to rely on ambient SSH config. */
47	  sshKeyPath?: string;
48	  /**
49	   * Upper bound on the random pre-commit jitter in seconds.
50	   * Actual jitter is random(50ms, min(500ms, jitterMaxSeconds * 1000)).
51	   * Default: 0.5.
52	   */
53	  jitterMaxSeconds?: number;
54	  /**
55	   * Base branch of the workspace repo (e.g. "main").
56	   * The orchestrator is reset to this branch before claiming, and losers are
57	   * reset back to it after a push rejection.
58	   * Default: "main".
59	   */
60	  baseBranch?: string;
61	  /** Skip the pre-commit jitter sleep. Intended for unit/integration tests. */
62	  skipJitter?: boolean;
63	  /**
64	   * Skip all git operations (fetch / checkout / add / commit / push).
65	   * The task YAML is still mutated on disk.
66	   * Intended for unit tests that do not set up a real git repo.
67	   */
68	  skipGit?: boolean;
69	}
70	
71	/**
72	 * Result returned by claimTask.
73	 *   won: true                     — this agent owns the task; proceed with implementation.
74	 *   won: false, reason: ...       — claim failed or was lost.
75	 */
76	export type ClaimResult =
77	  | { won: true }
78	  | {
79	      won: false;
80	      reason:
81	        | "task_not_ready"           // task.status !== "ready" when we read it
82	        | "push_rejected"            // another agent's commit is on remote HEAD
83	        | "post_claim_mismatch"      // won the push but YAML doesn't confirm our claim
84	        | "branch_blocked_recovery"; // task branch exists + blocked_context non-null → S5
85	    };
86	
87	// ── Internal helpers ──────────────────────────────────────────────────────────
88	
89	function sleep(ms: number): Promise<void> {
90	  return new Promise((resolve) => setTimeout(resolve, ms));
91	}
92	
93	function readTask(
94	  workspaceRoot: string,
95	  featureId: string,
96	  taskId: string,
97	): Task {
98	  return parseYaml(
99	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
100	  ) as Task;
101	}
102	
103	function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
104	  writeFileSync(
105	    taskYamlAbsPath(workspaceRoot, featureId, task.id),
106	    yamlStringify(task),
107	    "utf-8",
108	  );
109	}
110	
111	
112	/**
113	 * Check whether a branch exists on origin.
114	 * Uses `git ls-remote --exit-code`: exit 0 = found, exit 2 = not found.
115	 */
116	function remoteHasBranch(
117	  workspaceRoot: string,
118	  branch: string,
119	  env: NodeJS.ProcessEnv,
120	): boolean {
121	  const result = spawnSync(
122	    "git",
123	    ["-C", workspaceRoot, "ls-remote", "--exit-code", "origin", `refs/heads/${branch}`],
124	    { env, encoding: "utf-8" },
125	  );
126	  return result.status === 0;
127	}
128	
129	// ── Public API ────────────────────────────────────────────────────────────────
130	
131	/**
132	 * Attempt to atomically claim a `ready` task.
133	 *
134	 * On success the management repo's local HEAD is on the task branch
135	 * (feature/<featureId>-<taskId>) with the claim commit. The task YAML has
136	 * status: in_progress and task.branch set to the canonical task branch name.
137	 *
138	 * @returns `{ won: true }` if this agent successfully claimed the task.
139	 *          `{ won: false, reason }` if the claim failed or was lost.
140	 */
141	export async function claimTask(opts: ClaimTaskOptions): Promise<ClaimResult> {
142	  const {
143	    workspaceRoot,
144	    taskId,
145	    featureId,
146	    gitAuthorEmail,
147	    gitAuthorName = gitAuthorEmail,
148	    sshKeyPath,
149	    jitterMaxSeconds = 0.5,
150	    baseBranch = "main",
151	    skipJitter = false,
152	    skipGit = false,
153	  } = opts;
154	
155	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
156	
157	  // ── 1. Fetch + reset to clean base branch ─────────────────────────────────
158	  // Always start from a known-good state so the task YAML reflects the latest
159	  // remote state, not a stale local copy.
160	  if (!skipGit) {
161	    try {
162	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
163	      execSync(
164	        `git -C "${workspaceRoot}" reset --hard "origin/${baseBranch}"`,
165	        { env, stdio: "pipe" },
166	      );
167	    } catch {
168	      return { won: false, reason: "push_rejected" };
169	    }
170	  }
171	
172	  // ── 2. Read task from disk; verify it is still ready ─────────────────────
173	  // `let` so we can rebind after inheriting an existing task branch (case b).
174	  let task = readTask(workspaceRoot, featureId, taskId);
175	  if (task.status !== "ready") {
176	    return { won: false, reason: "task_not_ready" };
177	  }
178	
179	  // ── 3. Determine task branch; handle branch-exists cases ─────────────────
180	  const branch = taskBranchName(featureId, taskId);
181	
182	  if (!skipGit) {
183	    const branchExists = remoteHasBranch(workspaceRoot, branch, env);
184	
185	    if (!branchExists) {
186	      // Case a: first claim — create the task branch from current HEAD (clean main).
187	      try {
188	        execSync(
189	          `git -C "${workspaceRoot}" checkout -b "${branch}"`,
190	          { env, stdio: "pipe" },
191	        );
192	      } catch {
193	        tryResetToRemote(workspaceRoot, baseBranch, env);
194	        return { won: false, reason: "push_rejected" };
195	      }
196	    } else if (!task.blocked_context) {
197	      // Case b: branch exists + no blocked_context — interrupted prior claim.
198	      // Checkout the existing branch and reset to origin state.
199	      try {
200	        execSync(
201	          `git -C "${workspaceRoot}" checkout "${branch}"`,
202	          { env, stdio: "pipe" },
203	        );
204	        execSync(
205	          `git -C "${workspaceRoot}" reset --hard "origin/${branch}"`,
206	          { env, stdio: "pipe" },
207	        );
208	      } catch {
209	        tryResetToRemote(workspaceRoot, baseBranch, env);
210	        return { won: false, reason: "push_rejected" };
211	      }
212	      // Re-read YAML from the branch state — another agent may have already
213	      // committed a claim here while we were checking. If the task is no longer
214	      // "ready" on this branch we lost the race.
215	      task = readTask(workspaceRoot, featureId, taskId);
216	      if (task.status !== "ready") {
217	        tryResetToRemote(workspaceRoot, baseBranch, env);
218	        return { won: false, reason: "push_rejected" };
219	      }
220	    } else {
221	      // Case c: branch exists + blocked_context non-null — blocked recovery (S5).
222	      // Do not attempt a new claim; the caller handles the recovery flow.
223	      return { won: false, reason: "branch_blocked_recovery" };
224	    }
225	  }
226	
227	  // ── 4. Pre-commit jitter ──────────────────────────────────────────────────
228	  if (!skipJitter) {
229	    const maxMs = Math.min(jitterMaxSeconds * 1000, 500);
230	    const minMs = 50;
231	    const jitterMs = minMs + Math.random() * Math.max(0, maxMs - minMs);
232	    await sleep(jitterMs);
233	  }
234	
235	  // ── 5. Mutate task YAML ───────────────────────────────────────────────────
236	  const now = new Date().toISOString();
237	  task.status = "in_progress";
238	  task.branch = branch;
239	  task.execution.last_updated_by = gitAuthorEmail;
240	  task.execution.last_updated_at = now;
241	  task.log.push({
242	    action: "claimed",
243	    by: gitAuthorEmail,
244	    at: now,
245	    note: "Claimed via git-based claim protocol.",
246	  });
247	  writeTask(workspaceRoot, featureId, task);
248	
249	  if (skipGit) {
250	    return { won: true };
251	  }
252	
253	  // ── 6. git add + commit ───────────────────────────────────────────────────
254	  const relPath = taskYamlRelPath(featureId, taskId);
255	
256	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
257	    env,
258	    stdio: "pipe",
259	  });
260	  execSync(
261	    `git -C "${workspaceRoot}" commit -m "chore(${taskId}): claim — status in_progress"`,
262	    { env, stdio: "pipe" },
263	  );
264	
265	  // Record the commit SHA — this is the arbitration token.
266	  const ourSha = execSync(
267	    `git -C "${workspaceRoot}" rev-parse HEAD`,
268	    { env, stdio: "pipe", encoding: "utf-8" },
269	  ).trim();
270	
271	  // ── 7. git push to task branch ────────────────────────────────────────────
272	  const pushResult = spawnSync(
273	    "git",
274	    ["-C", workspaceRoot, "push", "origin", branch],
275	    { env, encoding: "utf-8" },
276	  );
277	
278	  if (pushResult.status !== 0) {
279	    // Push rejected — fetch and compare SHA against origin/<branch>.
280	    try {
281	      execSync(
282	        `git -C "${workspaceRoot}" fetch origin "${branch}"`,
283	        { env, stdio: "pipe" },
284	      );
285	    } catch {
286	      tryResetToRemote(workspaceRoot, baseBranch, env);
287	      return { won: false, reason: "push_rejected" };
288	    }
289	
290	    const remoteHeadSha = execSync(
291	      `git -C "${workspaceRoot}" rev-parse "origin/${branch}"`,
292	      { env, stdio: "pipe", encoding: "utf-8" },
293	    ).trim();
294	
295	    if (remoteHeadSha !== ourSha) {
296	      // Another agent's commit is on the remote — we lost.
297	      tryResetToRemote(workspaceRoot, baseBranch, env);
298	      return { won: false, reason: "push_rejected" };
299	    }
300	
301	    // remoteHeadSha === ourSha: our commit landed despite the rejection. We won.
302	  }
303	
304	  // ── 8. Post-claim verification ────────────────────────────────────────────
305	  const confirmed = readTask(workspaceRoot, featureId, taskId);
306	  if (
307	    confirmed.status !== "in_progress" ||
308	    confirmed.execution.last_updated_by !== gitAuthorEmail
309	  ) {
310	    return { won: false, reason: "post_claim_mismatch" };
311	  }
312	
313	  return { won: true };
314	}
