317	
318	/**
319	 * Best-effort reset of the local repo to origin/<baseBranch>.
320	 * Used after losing a push race so the next activation starts from a clean state.
321	 */
322	function tryResetToRemote(
323	  workspaceRoot: string,
324	  baseBranch: string,
325	  env: NodeJS.ProcessEnv,
326	): void {
327	  try {
328	    execSync(
329	      `git -C "${workspaceRoot}" checkout "${baseBranch}"`,
330	      { env, stdio: "pipe" },
331	    );
332	    execSync(
333	      `git -C "${workspaceRoot}" reset --hard "origin/${baseBranch}"`,
334	      { env, stdio: "pipe" },
335	    );
336	  } catch {
337	    // Intentionally ignored — best-effort cleanup.
338	  }
339	}
