7	/** Validated agent configuration. */
8	export interface AgentConfig {
9	  /** SSH URLs of workspace repositories this agent watches. */
10	  watches: string[];
11	  /** Kill switch — false means exit immediately. */
12	  enabled: boolean;
13	  /** Maximum random jitter (seconds) before a claim commit. */
14	  jitter_max_seconds: number;
15	  /** Hard budget limits per task activation. */
16	  budget: {
17	    /** Max tokens (input + output) per task. */
18	    max_tokens_per_task: number;
19	    /** Max tool-use loop iterations per task. */
20	    max_iterations: number;
21	  };
22	  /** Per-run JSONL event log configuration. */
23	  log_sink: {
24	    /** Whether to write event logs. */
25	    enabled: boolean;
26	  };
27	  /**
28	   * Seconds to sleep between poll cycles when no eligible task is found,
29	   * and after a successful task run.
30	   * Set to 0 for single-shot mode (process exits after one cycle).
31	   * Defaults to 60 when omitted.
32	   */
33	  idle_sleep_seconds?: number;
34	  /**
35	   * How often (in seconds) the agent checks in_review PR mergeability.
36	   * The in_review pass is skipped if it ran within this window.
37	   * Defaults to idle_sleep_seconds when omitted.
38	   * Raise to 300 in production to reduce GitHub API call frequency.
39	   */
40	  pr_poll_interval_seconds?: number;
41	}
42	
43	export interface ValidationError {
44	  /** JSON pointer to the offending field (e.g. "/budget/max_tokens_per_task"). */
45	  path: string;
46	  /** Human-readable description of what went wrong. */
47	  message: string;
48	}
49	
50	export type ValidationResult =
51	  | { valid: true; config: AgentConfig }
52	  | { valid: false; errors: ValidationError[] };
53	
54	const __dirname = dirname(fileURLToPath(import.meta.url));
55	const SCHEMA_PATH = resolve(__dirname, "../../../../schemas/agent.schema.json");
56	
57	let _ajvValidate: ValidateFunction | null = null;
58	
59	function getValidator(schemaOverride?: object): ValidateFunction {
60	  if (schemaOverride) {
61	    const ajv = new Ajv.default({ allErrors: true });
62	    return ajv.compile(schemaOverride);
63	  }
64	  if (!_ajvValidate) {
65	    const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf-8"));
66	    const ajv = new Ajv.default({ allErrors: true });
67	    _ajvValidate = ajv.compile(schema);
68	  }
69	  return _ajvValidate;
70	}
71	
72	function formatAjvErrors(errors: ErrorObject[]): ValidationError[] {
73	  return errors.map((err: ErrorObject) => {
74	    const path = err.instancePath || "/";
75	    let message: string;
76	
77	    switch (err.keyword) {
78	      case "required":
79	        message = `Missing required field: ${err.params.missingProperty}`;
80	        break;
81	      case "additionalProperties":
82	        message = `Unknown field: ${err.params.additionalProperty}`;
83	        break;
84	      case "type":
85	        message = `Expected type "${err.params.type}", got ${typeof err.data}`;
86	        break;
87	      case "minimum":
88	        message = `Value must be >= ${err.params.limit}`;
89	        break;
90	      case "minItems":
91	        message = `Array must have at least ${err.params.limit} item(s)`;
92	        break;
93	      case "minLength":
94	        message = `String must not be empty`;
95	        break;
96	      default:
97	        message = err.message ?? "Validation failed";
98	    }
99	
100	    return { path, message };
101	  });
102	}
