1	/**
2	 * SSH key resolution — D1 (SSH_PRIVATE_KEY env var delivery).
3	 *
4	 * Priority:
5	 *   1. SSH_PRIVATE_KEY env var (raw PEM) → write to tempKeyPath (mode 0400)
6	 *   2. SSH_KEY_PATH env var → use as-is
7	 *   3. Neither → return undefined + set warned = true
8	 *
9	 * The function is extracted from main.ts so it can be unit-tested in isolation.
10	 */
11	
12	import { writeFileSync, unlinkSync, existsSync } from "node:fs";
13	
14	// Write to the agent user's home dir, not /tmp, so a root-owned leftover
15	// from a previous container run cannot block the write (EACCES).
16	// The file is removed before each write because a 0o400 file cannot be
17	// overwritten in place — container restarts (restart: unless-stopped) hit
18	// EACCES without the unlink.
19	export const TEMP_SSH_KEY_PATH = "/home/agent/.ssh/agent_id_rsa";
20	
21	export interface SSHKeyEnv {
22	  SSH_PRIVATE_KEY?: string;
23	  SSH_KEY_PATH?: string;
24	}
25	
26	export interface ResolveSSHKeyResult {
27	  /** Resolved path to the SSH private key file, or undefined if not available. */
28	  sshKeyPath: string | undefined;
29	  /** True when neither env var was set — caller should emit a warning. */
30	  warned: boolean;
31	}
32	
33	/**
34	 * Resolve the SSH key path from environment variables.
35	 *
36	 * @param env          - Object with SSH_PRIVATE_KEY and/or SSH_KEY_PATH fields.
37	 * @param writeFn      - Injectable write function (defaults to fs.writeFileSync).
38	 * @param tempKeyPath  - Temp file path for PEM content (defaults to TEMP_SSH_KEY_PATH).
39	 * @param existsFn     - Injectable existsSync (defaults to fs.existsSync).
40	 * @param unlinkFn     - Injectable unlinkSync (defaults to fs.unlinkSync).
41	 */
42	export function resolveSSHKey(
43	  env: SSHKeyEnv,
44	  writeFn: (path: string, data: string, opts: { mode: number }) => void = writeFileSync,
45	  tempKeyPath: string = TEMP_SSH_KEY_PATH,
46	  existsFn: (path: string) => boolean = existsSync,
47	  unlinkFn: (path: string) => void = unlinkSync,
48	): ResolveSSHKeyResult {
49	  if (env.SSH_PRIVATE_KEY) {
50	    if (existsFn(tempKeyPath)) unlinkFn(tempKeyPath);
51	    // Normalize literal \n (from Docker Compose env_file / YAML interpolation) to real newlines.
52	    const pem = env.SSH_PRIVATE_KEY.replace(/\\n/g, "\n");
53	    writeFn(tempKeyPath, pem, { mode: 0o400 });
54	    return { sshKeyPath: tempKeyPath, warned: false };
55	  }
56	  if (env.SSH_KEY_PATH) {
57	    return { sshKeyPath: env.SSH_KEY_PATH, warned: false };
58	  }
59	  return { sshKeyPath: undefined, warned: true };
60	}
