1	/**
2	 * Parses the `### Required skills` subsection for every task in a tasks.md file.
3	 *
4	 * Grammar (from technical-design.md §Q6 detail):
5	 *   - Task heading:      `## T<n> — <title>`  (must include the em-dash separator)
6	 *   - Skills block:      `### Required skills` within the task section
7	 *   - Skill entry:       `- <slug>` where slug matches `^[a-z0-9][a-z0-9-]*$`
8	 *   - Section boundary:  next `###`, `##`, or EOF
9	 *
10	 * Absence of `### Required skills` → task requires no skills (valid; no warning).
11	 * Any `- ` line with an invalid slug → emit `tasksmd_parse_warning` and omit that task.
12	 * Non-`- ` lines in the block (prose comments, blank lines) are silently ignored.
13	 */
14	
15	/** Slug must match directory names under workflow/technical_skills/. */
16	const SLUG_PATTERN = /^[a-z0-9][a-z0-9-]*$/;
17	
18	/** Skills extracted for one task. */
19	export interface TaskSkillInfo {
20	  requiredSkills: string[];
21	}
22	
23	/** Emitted to stdout when a ### Required skills subsection is malformed. */
24	export interface TasksMdParseWarning {
25	  type: "tasksmd_parse_warning";
26	  taskId: string;
27	  reason: string;
28	}
29	
30	function emitWarning(warning: TasksMdParseWarning): void {
31	  console.log(JSON.stringify(warning));
32	}
33	
34	/**
35	 * Extract the body of a task section from after its heading line to the next
36	 * `## ` heading or EOF.
37	 */
38	function extractTaskSection(content: string, numericId: string): string | null {
39	  // Heading must contain the em-dash separator: ## T<n> — <title>
40	  const headingRegex = new RegExp(`^## T${numericId}\\s+—`, "m");
41	  const headingMatch = headingRegex.exec(content);
42	  if (!headingMatch) return null;
43	
44	  const headingLineEnd = content.indexOf("\n", headingMatch.index);
45	  if (headingLineEnd === -1) return null;
46	
47	  const afterHeading = content.slice(headingLineEnd + 1);
48	
49	  // Scope ends at the next `## ` heading
50	  const nextHeadingMatch = /^## /m.exec(afterHeading);
51	  return nextHeadingMatch ? afterHeading.slice(0, nextHeadingMatch.index) : afterHeading;
52	}
53	
54	/**
55	 * Extract the raw text of the `### Required skills` block from within a task
56	 * section. Returns null if the subsection is absent.
57	 */
58	function extractRequiredSkillsBlock(taskSection: string): string | null {
59	  const blockMatch = /^### Required skills[ \t]*(?:\n|$)/im.exec(taskSection);
60	  if (!blockMatch) return null;
61	
62	  const afterBlock = taskSection.slice(blockMatch.index + blockMatch[0].length);
63	
64	  // Block ends at the next subsection (### or ##) or end of task section
65	  const nextHeadingMatch = /^##+ /m.exec(afterBlock);
66	  return nextHeadingMatch ? afterBlock.slice(0, nextHeadingMatch.index) : afterBlock;
67	}
68	
69	/**
70	 * Parse a full tasks.md file and return required skills per task.
71	 *
72	 * Keys are task IDs (e.g. "T5"). Tasks with absent or empty `### Required skills`
73	 * sections are included with `requiredSkills: []`. Tasks with malformed sections
74	 * emit a `tasksmd_parse_warning` event and are **omitted** from the result —
75	 * the caller treats them as ineligible.
76	 *
77	 * @param content - Full text of a tasks.md file.
78	 * @returns Record mapping task ID → TaskSkillInfo.
79	 */
80	export function parseTasksMd(content: string): Record<string, TaskSkillInfo> {
81	  const result: Record<string, TaskSkillInfo> = {};
82	
83	  // Scan for task headings: ## T<n> — <title>
84	  const headingRegex = /^## T(\d+)\s+—/gm;
85	  let headingMatch: RegExpExecArray | null;
86	
87	  while ((headingMatch = headingRegex.exec(content)) !== null) {
88	    const numericId = headingMatch[1]!;
89	    const taskId = `T${numericId}`;
90	
91	    const taskSection = extractTaskSection(content, numericId);
92	    if (taskSection === null) {
93	      // Heading found but section could not be extracted — shouldn't happen
94	      emitWarning({
95	        type: "tasksmd_parse_warning",
96	        taskId,
97	        reason: "Could not extract task section — malformed tasks.md structure",
98	      });
99	      continue;
100	    }
101	
102	    const skillsBlock = extractRequiredSkillsBlock(taskSection);
103	
104	    if (skillsBlock === null) {
105	      // No ### Required skills subsection → task needs no skills
106	      result[taskId] = { requiredSkills: [] };
107	      continue;
108	    }
109	
110	    // Parse skill entries from the block
111	    const lines = skillsBlock.split("\n");
112	    const slugs: string[] = [];
113	    let malformed = false;
114	
115	    for (const line of lines) {
116	      const trimmed = line.trim();
117	      if (trimmed === "") continue; // blank lines are not skill entries
118	
119	      if (!trimmed.startsWith("- ")) {
120	        // Non-bullet lines (prose comments like "(empty — …)") are silently ignored
121	        continue;
122	      }
123	
124	      const slug = trimmed.slice(2).trim();
125	      if (!SLUG_PATTERN.test(slug)) {
126	        emitWarning({
127	          type: "tasksmd_parse_warning",
128	          taskId,
129	          reason: `Invalid slug "${slug}" in ### Required skills — must match ^[a-z0-9][a-z0-9-]*$`,
130	        });
131	        malformed = true;
132	        break;
133	      }
134	
135	      slugs.push(slug);
136	    }
137	
138	    if (!malformed) {
139	      result[taskId] = { requiredSkills: slugs };
140	    }
141	    // Malformed tasks are omitted; the warning already surfaced above
142	  }
143	
144	  return result;
145	}
