/**
 * Orchestrator side-effect: open an implementation-repo pull request.
 *
 * Replaces what the executor used to trigger via the `/pr-create` skill.
 * Called after the executor returns `terminal_status: "in_review"`.
 * Idempotent: if an open PR already exists on the branch it is reused.
 *
 * Uses `curl` via spawnSync — no `gh` CLI required.
 */

import { spawnSync } from "node:child_process";
import { parseGitHubCoords } from "../claim/open-workspace-pr.js";

export interface OpenImplPrOpts {
  /** SSH or HTTPS URL of the implementation repo (used to derive GitHub coords). */
  taskRepoUrl: string;
  /** Feature branch to open the PR from. */
  taskBranch: string;
  /** Base branch to merge into (e.g. "main"). */
  baseBranch: string;
  /** Feature ID — used in PR title. */
  featureId: string;
  /** Task ID — used in PR title. */
  taskId: string;
  /** Task title — used in PR body. */
  taskTitle: string;
  /** GitHub personal access token. */
  githubToken: string;
}

export interface OpenImplPrResult {
  prUrl: string;
  prNumber: number;
  alreadyExisted: boolean;
}

interface PrListItem {
  html_url: string;
  number: number;
}

function curlJson(args: string[]): unknown {
  const result = spawnSync("curl", args, {
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.error) throw result.error;
  const stdout = result.stdout ?? "";
  if (!stdout.trim()) {
    throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
  }
  try {
    return JSON.parse(stdout);
  } catch {
    throw new Error(`curl response is not valid JSON: ${stdout}`);
  }
}

/**
 * Open a pull request on the implementation repo from taskBranch → baseBranch.
 *
 * PR title format: `feat(<featureId>/T<n>): <taskTitle>` (per workspace convention).
 * Idempotent: reuses an existing open PR on the same branch if found.
 */
export async function openImplPr(opts: OpenImplPrOpts): Promise<OpenImplPrResult> {
  const {
    taskRepoUrl,
    taskBranch,
    baseBranch,
    featureId,
    taskId,
    taskTitle,
    githubToken,
  } = opts;

  const { owner, repo } = parseGitHubCoords(taskRepoUrl);

  // ── 1. Check for existing open PR ──────────────────────────────────────────
  const encodedHead = encodeURIComponent(`${owner}:${taskBranch}`);
  const listUrl =
    `https://api.github.com/repos/${owner}/${repo}/pulls` +
    `?head=${encodedHead}&state=open`;

  const pullsList = curlJson([
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    listUrl,
  ]) as PrListItem[];

  if (Array.isArray(pullsList) && pullsList.length > 0) {
    return {
      prUrl: pullsList[0].html_url,
      prNumber: pullsList[0].number,
      alreadyExisted: true,
    };
  }

  // ── 2. Create new PR ────────────────────────────────────────────────────────
  const prTitle = `feat(${featureId}/${taskId}): ${taskTitle}`;
  const prBody =
    `Task: ${taskId}\nFeature: ${featureId}\nBranch: \`${taskBranch}\``;

  const createUrl = `https://api.github.com/repos/${owner}/${repo}/pulls`;
  const requestBody = JSON.stringify({
    title: prTitle,
    body: prBody,
    head: taskBranch,
    base: baseBranch,
  });

  const created = curlJson([
    "-s", "-X", "POST",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    "-H", "Content-Type: application/json",
    "-d", requestBody,
    createUrl,
  ]) as { html_url?: string; number?: number };

  if (!created.html_url || !created.number) {
    throw new Error(
      `GitHub API PR creation failed. Response: ${JSON.stringify(created)}`,
    );
  }

  return {
    prUrl: created.html_url,
    prNumber: created.number,
    alreadyExisted: false,
  };
}

