45	    sshKeyPath,
46	    commitMessage,
47	  } = opts;
48	
49	  const at = entry.at ?? new Date().toISOString();
50	  const fullEntry: TaskLogEntry = { ...entry, at } as TaskLogEntry;
51	
52	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
53	  let task: Task;
54	  try {
55	    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
56	  } catch (e) {
