1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync } from "node:child_process";
24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
25	import { runBootstrap } from "./bootstrap/bootstrap.js";
26	import { resolveSSHKey } from "./resolve-ssh-key.js";
27	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "./paths.js";
28	import { findEligibleTasks } from "./eligibility/match.js";
29	import { claimTask } from "./claim/claim-task.js";
30	import { openWorkspacePr, parseGitHubCoords } from "./claim/open-workspace-pr.js";
31	import type { Task, TaskLogEntry } from "./types/task.js";
32	import { generateBriefing } from "./briefing/agent-context.js";
33	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
34	import { resolveModel } from "./config/resolve-model-policy.js";
35	import { parseModelOverrides } from "./config/parse-model-overrides.js";
36	import type { ModelPolicy } from "./config/resolve-model-policy.js";
37	import { pullWorkspaces } from "./poll/pull-workspaces.js";
38	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
39	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
40	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
41	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
42	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
43	import { SubProcessAdapter } from "./adapter/spawn.js";
44	import type { ExecutorInput } from "./adapter/adapter.js";
45	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
46	import { appendLogEntry } from "./side-effects/append-log.js";
47	import { openImplPr } from "./side-effects/open-pr.js";
48	import { buildGitEnv } from "./git-env.js";
49	
50	// ── Helpers ───────────────────────────────────────────────────────────────────
51	
52	function requireEnv(name: string): string {
53	  const val = process.env[name];
54	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
55	  return val;
56	}
57	
58	function extractRepoName(url: string): string {
59	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
60	  return match?.[1] ?? url;
61	}
62	
63	function emit(event: Record<string, unknown>): void {
64	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
65	}
66	
67	function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
68	  type RepoEntry = { id: string; github: string; local_path?: string };
69	  const yaml = parseYaml(
70	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
71	  ) as { repos: RepoEntry[] };
72	  const repo = yaml.repos.find((r) => r.id === repoId);
73	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
74	  if (!repo.local_path?.startsWith("env:")) {
75	    throw new Error(`Repo "${repoId}" has no "local_path: env:<VAR>" declaration.`);
76	  }
77	  const envVar = repo.local_path.slice(4);
78	  const val = process.env[envVar];
79	  if (!val) throw new Error(`Env var ${envVar} is not set for repo "${repoId}".`);
80	  return val;
81	}
82	
83	function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
84	  type RepoEntry = { id: string; base_branch?: string };
85	  const yaml = parseYaml(
86	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
87	  ) as { repos: RepoEntry[] };
88	  const repo = yaml.repos.find((r) => r.id === repoId);
89	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
90	  return repo.base_branch ?? "main";
91	}
92	
93	function resolveRepoGitUrl(workspaceRoot: string, repoId: string): string {
94	  type RepoEntry = { id: string; github: string };
95	  const yaml = parseYaml(
96	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
97	  ) as { repos: RepoEntry[] };
98	  const repo = yaml.repos.find((r) => r.id === repoId);
99	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
100	  return repo.github;
101	}
102	
103	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
104	  const task = parseYaml(
105	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
106	  ) as { repo: string };
107	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
108	  return task.repo;
109	}
110	
111	function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
112	  const yaml = parseYaml(
113	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
114	  ) as { model_policy?: ModelPolicy };
115	  if (yaml.model_policy) return yaml.model_policy;
116	  const defaultPhase = { allowed: ["claude-sonnet-4-6"], default: "claude-sonnet-4-6" };
117	  return {
118	    implementation: defaultPhase,
119	    self_review: defaultPhase,
120	    pr_description: defaultPhase,
121	    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
122	  };
123	}
124	
125	function parseManagementRepoCoords(
126	  workspaceRoot: string,
127	): { owner: string; repo: string; baseBranch: string } {
128	  type RepoEntry = { id: string; github: string; base_branch?: string };
129	  const yaml = parseYaml(
130	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
131	  ) as { management_repo: string; repos: RepoEntry[] };
132	  const mgmtId = yaml.management_repo;
133	  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
134	  if (!mgmtRepo) throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml`);
135	  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
136	  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main" };
137	}
138	
139	/**
140	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
141	 * Commits and pushes to the task branch. Throws on error.
142	 */
143	function writeRagPreFlight(
144	  workspaceRoot: string,
145	  featureId: string,
146	  taskId: string,
147	  taskBranch: string,
148	  gitAuthorEmail: string,
149	  sshKeyPath: string | undefined,
150	  ragPreFlight: { query: string; injected: boolean; summary: string },
151	): void {
152	  const now = new Date().toISOString();
153	  const entry: TaskLogEntry = {
154	    action: "rag_pre_flight",
155	    by: gitAuthorEmail,
156	    at: now,
157	    rag_context_injected: ragPreFlight.injected,
158	    rag_summary: ragPreFlight.summary,
159	    rag_query: ragPreFlight.query,
160	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
161	  };
162	
163	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
164	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
165	  task.log.push(entry);
166	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
167	
168	  const relPath = taskYamlRelPath(featureId, taskId);
169	  const gitOpts = {
170	    cwd: workspaceRoot,
171	    encoding: "utf-8" as const,
172	    env: buildGitEnv(sshKeyPath),
173	    timeout: 30_000,
174	    stdio: "pipe" as const,
175	  };
176	  execSync(`git add "${relPath}"`, gitOpts);
177	  execSync(
178	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
179	    gitOpts,
180	  );
181	  execSync(`git push origin "${taskBranch}"`, gitOpts);
182	}
183	
184	// ── Main ──────────────────────────────────────────────────────────────────────
185	
186	async function main(): Promise<number> {
187	  let agentYamlPath: string;
188	  let workflowLocalPath: string;
189	  let workspacesRoot: string;
190	  let gitAuthorEmail: string;
191	
192	  try {
193	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
194	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
195	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
196	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
197	  } catch (e) {
198	    emit({ type: "fatal_missing_env", details: (e as Error).message });
199	    return 4;
200	  }
201	
202	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
203	
204	  const sshResolution = resolveSSHKey(process.env);
205	  const sshKeyPath = sshResolution.sshKeyPath;
206	  if (sshResolution.warned) {
207	    emit({ type: "warn_no_ssh_key", note: "Neither SSH_PRIVATE_KEY nor SSH_KEY_PATH is set." });
208	  }
209	
210	  const bootstrapResult = await runBootstrap({
211	    agentYamlPath,
212	    workflowLocalPath,
213	    workflowUrl: process.env.WORKFLOW_URL,
214	    workspacesRoot,
215	    sshKeyPath,
216	  });
217	
218	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
219	
220	  const config = bootstrapResult.config!;
221	  const githubToken = process.env.GITHUB_TOKEN ?? "";
222	  if (!githubToken) emit({ type: "warn_no_github_token" });
223	
224	  let lastPrPollAt: number | null = null;
225	
226	  async function runOneCycle(): Promise<CycleOutcome> {
227	    const pullResults = pullWorkspaces({
228	      watchUrls: config.watches,
229	      sshKeyPath,
230	      workspacesRoot,
231	      workflowUrl: process.env.WORKFLOW_URL,
232	      workflowLocalPath,
233	      emit,
234	    });
235	
236	    const haltedUrls = new Set(
237	      pullResults
238	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
239	        .map((r) => r.url),
240	    );
241	
242	    let outcome: CycleOutcome = "idle";
243	    const pulledWorkspaceRoots: string[] = [];
244	
245	    outerLoop:
246	    for (const watchUrl of config.watches) {
247	      if (haltedUrls.has(watchUrl)) continue;
248	
249	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
250	      pulledWorkspaceRoots.push(workspaceLocalPath);
251	
252	      if (!existsSync(workspaceLocalPath)) {
253	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
254	        continue;
255	      }
256	
257	      let eligibleTasks;
258	      try {
259	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
260	      } catch (e) {
261	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
262	        continue;
263	      }
264	
265	      if (eligibleTasks.length === 0) {
266	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
267	        continue;
268	      }
269	
270	      for (const { task, featureId } of eligibleTasks) {
271	        const claimResult = await claimTask({
272	          workspaceRoot: workspaceLocalPath,
273	          taskId: task.id,
274	          featureId,
275	          gitAuthorEmail,
276	          gitAuthorName,
277	          sshKeyPath,
278	          jitterMaxSeconds: config.jitter_max_seconds,
279	        });
280	
281	        const taskBranch = taskBranchName(featureId, task.id);
282	
283	        if (!claimResult.won) {
284	          if (claimResult.reason !== "branch_blocked_recovery") {
285	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
286	            continue;
287	          }
288	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
289	        } else {
290	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
291	        }
292	
293	        // ── Open management-repo PR ───────────────────────────────────────────
294	        if (githubToken) {
295	          try {
296	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
297	            await openWorkspacePr({
298	              workspaceRoot: workspaceLocalPath,
299	              featureId,
300	              taskId: task.id,
301	              branch: taskBranch,
302	              baseBranch: mgmtCoords.baseBranch,
303	              githubToken,
304	              repoOwner: mgmtCoords.owner,
305	              repoName: mgmtCoords.repo,
306	              gitAuthorEmail,
307	              gitAuthorName,
308	              sshKeyPath,
309	            });
310	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
311	          } catch (e) {
312	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
313	          }
314	        }
315	
316	        // ── Resolve model + task repo ────────────────────────────────────────
317	        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
318	        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
319	        const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
320	        const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
321	
322	        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
323	        let taskModelOverrides = {};
324	        try {
325	          taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
326	        } catch { /* non-fatal */ }
327	
328	        const implementationModel = resolveModel(
329	          workspaceModelPolicy,
330	          taskModelOverrides,
331	          "implementation",
332	          task.id,
333	        );
334	
335	        // ── RAG pre-flight ───────────────────────────────────────────────────
336	        const mcpRagUrl = process.env.MCP_RAG_URL;
337	        const workspaceYaml = parseYaml(
338	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
339	        ) as { workspace_id: string };
340	        const ragQuery = `${task.title} ${featureId}`;
341	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
342	
343	        try {
344	          writeRagPreFlight(
345	            workspaceLocalPath,
346	            featureId,
347	            task.id,
348	            taskBranch,
349	            gitAuthorEmail,
350	            sshKeyPath,
351	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
352	          );
353	        } catch (e) {
354	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details: String(e) });
355	          continue;
356	        }
357	
358	        // ── Generate briefing ────────────────────────────────────────────────
359	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
360	        const baseContext = generateBriefing({
361	          taskId: task.id,
362	          featureId,
363	          taskTitle: task.title,
364	          taskBranch,
365	          taskRepo: task.repo,
366	          taskRepoRoot,
367	          workspaceRoot: workspaceLocalPath,
368	          gitAuthorEmail,
369	          gitAuthorName,
370	          implementationModel,
371	          resultPath,
372	        });
373	        const briefingContent = ragPreFlight.block
374	          ? `${baseContext}\n\n${ragPreFlight.block}`
375	          : baseContext;
376	
377	        const briefingDir = join(tmpdir(), `briefing-${task.id}`);
378	        mkdirSync(briefingDir, { recursive: true });
379	        const briefingPath = join(briefingDir, "briefing.md");
380	        writeFileSync(briefingPath, briefingContent, "utf-8");
381	
382	        // ── Build ExecutorInput ──────────────────────────────────────────────
383	        const input: ExecutorInput = {
384	          taskId: task.id,
385	          featureId,
386	          workspaceId: workspaceYaml.workspace_id,
387	          taskRepoUrl,
388	          taskRepoBranch: taskBranch,
389	          taskRepoPath: taskRepoRoot,
390	          briefingPath,
391	          resultPath,
392	          budgetTokens: config.budget.max_tokens_per_task,
393	          sshKeyPath: sshKeyPath ?? "",
394	          githubToken,
395	        };
396	
397	        // ── Run executor ─────────────────────────────────────────────────────
398	        const perTaskAdapter = new SubProcessAdapter({
399	          extraEnv: {
400	            WORKSPACE_ROOT: workspaceLocalPath,
401	            TASK_BRANCH: taskBranch,
402	            GIT_AUTHOR_EMAIL: gitAuthorEmail,
403	            GIT_AUTHOR_NAME: gitAuthorName,
404	            WORKFLOW_LOCAL_PATH: workflowLocalPath,
405	            MAX_TURNS: String(config.budget.max_iterations),
406	            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
407	            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
408	            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
409	              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
410	              : {}),
411	          },
412	        });
413	
414	        const execResult = await perTaskAdapter.run(input);
415	
416	        emit({
417	          type: "executor_result",
418	          task_id: task.id,
419	          feature_id: featureId,
420	          terminal_status: execResult.terminal_status,
421	        });
422	
423	        // ── Side-effects ─────────────────────────────────────────────────────
424	        if (execResult.terminal_status === "in_review") {
425	          let prUrl: string | undefined;
426	          if (githubToken) {
427	            try {
428	              const prResult = await openImplPr({
429	                taskRepoUrl,
430	                taskBranch,
431	                baseBranch: taskBaseBranch,
432	                featureId,
433	                taskId: task.id,
434	                taskTitle: task.title,
435	                githubToken,
436	              });
437	              prUrl = prResult.prUrl;
438	              emit({ type: "impl_pr_opened", task_id: task.id, feature_id: featureId, pr_url: prUrl });
439	            } catch (e) {
440	              emit({ type: "impl_pr_failed", task_id: task.id, details: String(e) });
441	            }
442	          }
443	
444	          const mutateErr = mutateTaskYaml({
445	            workspaceRoot: workspaceLocalPath,
446	            featureId,
447	            taskId: task.id,
448	            taskBranch,
449	            result: execResult,
450	            prUrl,
451	            gitAuthorEmail,
452	            gitAuthorName,
453	            sshKeyPath,
454	          });
455	          if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
456	
457	          const logErr = appendLogEntry({
458	            workspaceRoot: workspaceLocalPath,
459	            featureId,
460	            taskId: task.id,
461	            taskBranch,
462	            entry: {
463	              action: "in_review",
464	              by: gitAuthorEmail,
465	              note: prUrl ? `Implementation PR opened: ${prUrl}` : "Implementation complete.",
466	            },
467	            gitAuthorEmail,
468	            gitAuthorName,
469	            sshKeyPath,
470	          });
471	          if (logErr) emit({ type: "append_log_failed", task_id: task.id, details: logErr });
472	        } else {
473	          const mutateErr = mutateTaskYaml({
474	            workspaceRoot: workspaceLocalPath,
475	            featureId,
476	            taskId: task.id,
477	            taskBranch,
478	            result: execResult,
479	            gitAuthorEmail,
480	            gitAuthorName,
481	            sshKeyPath,
482	          });
483	          if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
484	
485	          const logErr = appendLogEntry({
486	            workspaceRoot: workspaceLocalPath,
487	            featureId,
488	            taskId: task.id,
489	            taskBranch,
490	            entry: {
491	              action: "blocked",
492	              by: gitAuthorEmail,
493	              note: execResult.blocked_reason ?? "executor returned non-in_review status",
494	            },
495	            gitAuthorEmail,
496	            gitAuthorName,
497	            sshKeyPath,
498	          });
499	          if (logErr) emit({ type: "append_log_failed", task_id: task.id, details: logErr });
500	        }
501	
502	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: execResult.terminal_status });
503	        outcome = "ran_task";
504	        break outerLoop;
505	      }
506	    }
507	
508	    // ── In-review PR poll ─────────────────────────────────────────────────────
509	    if (githubToken) {
510	      const prPollIntervalMs =
511	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
512	      const now = Date.now();
513	
514	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
515	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
516	        try {
517	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
518	            workspaceRoots: pulledWorkspaceRoots,
519	            githubToken,
520	            emit,
521	          });
522	
523	          for (const wsRoot of pulledWorkspaceRoots) {
524	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
525	            if (wsResults.some((r) => r.mergeable === false)) {
526	              await handleMergeConflicts({
527	                prResults: wsResults,
528	                workspaceRoot: wsRoot,
529	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
530	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
531	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
532	                gitAuthorEmail,
533	                gitAuthorName,
534	                sshKeyPath,
535	                emit,
536	              });
537	            }
538	          }
539	
540	          for (const wsRoot of pulledWorkspaceRoots) {
541	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
542	            if (wsResults.some((r) => r.hasOpenComments === true)) {
543	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
544	              await handleDraftReviews({
545	                prResults: wsResults,
546	                workspaceRoot: wsRoot,
547	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
548	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
549	                resolveImplementationModel: (fId, tId) => {
550	                  try {
551	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
552	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
553	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
554	                  } catch {
555	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
556	                  }
557	                },
558	                gitAuthorEmail,
559	                gitAuthorName,
560	                sshKeyPath,
561	                workflowLocalPath,
562	                maxTurns: config.budget.max_iterations,
563	                maxTokens: config.budget.max_tokens_per_task,
564	                logSinkEnabled: config.log_sink.enabled,
565	                workspaceId: (() => {
566	                  try {
567	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
568	                  } catch { return ""; }
569	                })(),
570	                githubToken,
571	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
572	                emit,
573	              });
574	            }
575	          }
576	
577	          for (const wsRoot of pulledWorkspaceRoots) {
578	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
579	            if (wsResults.some((r) => r.merged === true)) {
580	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
581	              await handleMergedPrs({
582	                prResults: wsResults,
583	                workspaceRoot: wsRoot,
584	                mgmtRepoOwner: mgmtCoords.owner,
585	                mgmtRepoName: mgmtCoords.repo,
586	                mgmtBaseBranch: mgmtCoords.baseBranch,
587	                githubToken,
588	                gitAuthorEmail,
589	                gitAuthorName,
590	                sshKeyPath,
591	                emit,
592	              });
593	            }
594	          }
595	
596	          for (const wsRoot of pulledWorkspaceRoots) {
597	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
598	            if (wsRecoveries.length > 0) {
599	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
600	              await handleWorkspacePrRecoveries({
601	                recoveries: wsRecoveries,
602	                mgmtRepoOwner: mgmtCoords.owner,
603	                mgmtRepoName: mgmtCoords.repo,
604	                mgmtBaseBranch: mgmtCoords.baseBranch,
605	                githubToken,
606	                gitAuthorEmail,
607	                gitAuthorName,
608	                sshKeyPath,
609	                emit,
610	              });
611	            }
612	          }
613	        } catch (e) {
614	          emit({ type: "in_review_poll_error", details: String(e) });
615	        }
616	      }
617	    }
618	
619	    return outcome;
620	  }
621	
622	  await runAgentLoop({ config, runCycle: runOneCycle, emit });
623	  return 0;
624	}
625	
626	main()
627	  .then((code) => process.exit(code))
628	  .catch((e) => {
629	    try {
630	      console.log(JSON.stringify({
631	        type: "fatal_error",
632	        details: (e as Error).message ?? String(e),
633	        at: new Date().toISOString(),
634	      }));
635	    } catch { /* last resort */ }
636	    process.exit(4);
637	  });
