/**
 * Unit tests for side-effects/open-pr.ts (openImplPr).
 *
 * No real GitHub API calls — spawnSync (used for curl) is mocked via vi.mock.
 *
 * Covers:
 *   1. Existing open PR on branch → reuse it (no POST)
 *   2. No existing PR → POST creates new one
 *   3. POST response lacks html_url / number → throws
 *   4. PR title follows feat(<featureId>/<taskId>): <taskTitle> convention
 *   5. GET query includes head=owner:branch and state=open
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { spawnSync } from "node:child_process";
import { openImplPr } from "../src/side-effects/open-pr.js";

// ── Mock spawnSync (used by curlJson inside open-pr.ts) ───────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, spawnSync: vi.fn() };
});

afterEach(() => {
  vi.clearAllMocks();
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const TASK_REPO_URL = "git@github.com:myorg/my-impl-repo.git";
const TASK_BRANCH = "feature/my-feature-T1";
const BASE_BRANCH = "main";
const FEATURE_ID = "my-feature";
const TASK_ID = "T1";
const TASK_TITLE = "Add widget component";
const GITHUB_TOKEN = "ghp_test_token";

const EXISTING_PR_URL = "https://github.com/myorg/my-impl-repo/pull/7";
const EXISTING_PR_NUMBER = 7;
const NEW_PR_URL = "https://github.com/myorg/my-impl-repo/pull/42";
const NEW_PR_NUMBER = 42;

function mockSpawnResult(jsonBody: unknown): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: JSON.stringify(jsonBody),
    stderr: "",
    status: 0,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

const baseOpts = {
  taskRepoUrl: TASK_REPO_URL,
  taskBranch: TASK_BRANCH,
  baseBranch: BASE_BRANCH,
  featureId: FEATURE_ID,
  taskId: TASK_ID,
  taskTitle: TASK_TITLE,
  githubToken: GITHUB_TOKEN,
};

// ── 1. Existing PR → alreadyExisted: true ────────────────────────────────────

describe("openImplPr — existing open PR", () => {
  it("returns alreadyExisted: true and reuses the existing URL", async () => {
    vi.mocked(spawnSync).mockReturnValueOnce(
      mockSpawnResult([{ html_url: EXISTING_PR_URL, number: EXISTING_PR_NUMBER }]),
    );

    const result = await openImplPr(baseOpts);

    expect(result.prUrl).toBe(EXISTING_PR_URL);
    expect(result.prNumber).toBe(EXISTING_PR_NUMBER);
    expect(result.alreadyExisted).toBe(true);
  });

  it("does not call POST when an existing PR is found", async () => {
    vi.mocked(spawnSync).mockReturnValueOnce(
      mockSpawnResult([{ html_url: EXISTING_PR_URL, number: EXISTING_PR_NUMBER }]),
    );

    await openImplPr(baseOpts);

    // Only one spawnSync call (the GET) — no POST.
    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(1);
    const [, args] = vi.mocked(spawnSync).mock.calls[0];
    expect((args as string[]).includes("POST")).toBe(false);
  });
});

