/**
 * Unit tests for side-effects/mutate-task-yaml.ts (mutateTaskYaml).
 *
 * Git operations (execSync, spawnSync) are mocked via vi.mock.
 * File I/O uses real temp directories.
 *
 * Covers:
 *   1. terminal_status: "in_review" → task.status = "in_review", pr set
 *   2. terminal_status: "in_review" without prUrl → pr not set (no crash)
 *   3. terminal_status: "blocked" → task.status = "blocked", blocked_reason + suggestion
 *   4. terminal_status: "blocked" without suggestion → task.blocked_suggestion not set
 *   5. terminal_status: "failed" → task.status = "blocked", blocked_reason = "executor_failed:..."
 *   6. Missing YAML file → returns error string (non-throwing)
 *   7. execution.last_updated_by is set on every call
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import { mutateTaskYaml } from "../src/side-effects/mutate-task-yaml.js";

// ── Mock git operations ───────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T2";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Test Agent";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Test Task",
    repo: "test-repo",
    status: "in_progress",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task): string {
  const dir = mkdtempSync(join(tmpdir(), "mutate-yaml-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  return dir;
}

function readTaskFromWorkspace(wsRoot: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

function mockPushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

const baseOpts = {
  featureId: FEATURE_ID,
  taskId: TASK_ID,
  taskBranch: TASK_BRANCH,
  gitAuthorEmail: GIT_AUTHOR_EMAIL,
  gitAuthorName: GIT_AUTHOR_NAME,
};

// ── 1. in_review → task.status = "in_review", pr set ─────────────────────────

describe("mutateTaskYaml — in_review", () => {
  it("sets task.status to in_review and writes pr.url", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    const err = mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "in_review" },
      prUrl: "https://github.com/org/repo/pull/5",
    });

    expect(err).toBeUndefined();
    const task = readTaskFromWorkspace(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe("https://github.com/org/repo/pull/5");
    expect(task.pr.status).toBe("open");
  });

  it("does not crash when prUrl is undefined", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    const err = mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "in_review" },
    });

    expect(err).toBeUndefined();
    const task = readTaskFromWorkspace(wsRoot);
    expect(task.status).toBe("in_review");
  });
});

// ── 2. blocked → task.status = "blocked" ─────────────────────────────────────

describe("mutateTaskYaml — blocked", () => {
  it("sets task.status to blocked and writes blocked_reason", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    const err = mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "blocked", blocked_reason: "missing_tool" },
    });

    expect(err).toBeUndefined();
    const task = readTaskFromWorkspace(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("missing_tool");
  });

  it("writes blocked_suggestion when present", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: {
        terminal_status: "blocked",
        blocked_reason: "missing_tool",
        blocked_suggestion: "Install the required tool.",
      },
    });

    const task = readTaskFromWorkspace(wsRoot);
    expect(task.blocked_suggestion).toBe("Install the required tool.");
  });

  it("does not write blocked_suggestion when absent", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "blocked", blocked_reason: "no_progress" },
    });

    const task = readTaskFromWorkspace(wsRoot);
    expect(task.blocked_suggestion).toBeUndefined();
  });
});

// ── 3. failed → task.status = "blocked", blocked_reason = "executor_failed:..." ─

describe("mutateTaskYaml — failed", () => {
  it("sets task.status to blocked with executor_failed prefix", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: {
        terminal_status: "failed",
        blocked_reason: "executor_crashed (exit 1)",
      },
    });

    const task = readTaskFromWorkspace(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("executor_failed:executor_crashed (exit 1)");
  });

  it("uses 'unknown' when blocked_reason is absent in failed result", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "failed" },
    });

    const task = readTaskFromWorkspace(wsRoot);
    expect(task.blocked_reason).toBe("executor_failed:unknown");
  });
});

// ── 4. Missing YAML → returns error string ────────────────────────────────────

describe("mutateTaskYaml — file not found", () => {
  it("returns an error string instead of throwing when YAML is missing", () => {
    const wsRoot = mkdtempSync(join(tmpdir(), "mutate-yaml-empty-"));
    tmpDirs.push(wsRoot);
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const err = mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "in_review" },
    });

    expect(err).toBeDefined();
    expect(typeof err).toBe("string");
    expect(err).toContain("failed to read task YAML");
  });
});

// ── 5. execution.last_updated_by is set ──────────────────────────────────────

describe("mutateTaskYaml — execution metadata", () => {
  it("sets execution.last_updated_by to gitAuthorEmail", () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockPushSuccess());

    mutateTaskYaml({
      ...baseOpts,
      workspaceRoot: wsRoot,
      result: { terminal_status: "in_review" },
    });

    const task = readTaskFromWorkspace(wsRoot);
    expect(task.execution.last_updated_by).toBe(GIT_AUTHOR_EMAIL);
    expect(task.execution.last_updated_at).toBeTruthy();
  });
});

