1	/**
2	 * Orchestrator side-effect dispatcher.
3	 *
4	 * Translates an ExecutorResult into the correct set of side effects:
5	 *   in_review  → open impl PR, mutate task YAML to in_review, append log
6	 *   blocked    → mutate task YAML to blocked, append log
7	 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
8	 *
9	 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
10	 * verify the resulting task state without running the full bootstrap + poll loop.
11	 */
12	
13	import type { ExecutorResult } from "@workflow/runtime-abi";
14	import { mutateTaskYaml } from "./mutate-task-yaml.js";
15	import { appendLogEntry } from "./append-log.js";
16	import { openImplPr } from "./open-pr.js";
17	
18	export interface DispatchExecutorResultOpts {
19	  result: ExecutorResult;
20	  workspaceRoot: string;
21	  featureId: string;
22	  taskId: string;
23	  taskBranch: string;
24	  taskTitle: string;
25	  taskRepoUrl: string;
26	  taskBaseBranch: string;
27	  githubToken: string;
28	  gitAuthorEmail: string;
29	  gitAuthorName?: string;
30	  sshKeyPath?: string;
31	  emit: (event: Record<string, unknown>) => void;
32	}
33	
34	/**
35	 * Apply the side effects that correspond to an executor result.
36	 * Called by the orchestrator polling loop after adapter.run() returns.
37	 * Non-throwing: individual side-effect errors are emitted as events but do
38	 * not propagate — the cycle continues normally.
39	 */
40	export async function dispatchExecutorResult(
41	  opts: DispatchExecutorResultOpts,
42	): Promise<void> {
43	  const {
44	    result,
45	    workspaceRoot,
46	    featureId,
47	    taskId,
48	    taskBranch,
49	    taskTitle,
50	    taskRepoUrl,
51	    taskBaseBranch,
52	    githubToken,
53	    gitAuthorEmail,
54	    gitAuthorName,
55	    sshKeyPath,
56	    emit,
57	  } = opts;
58	
59	  if (result.terminal_status === "in_review") {
60	    let prUrl: string | undefined;
61	    if (githubToken) {
62	      try {
63	        const prResult = await openImplPr({
64	          taskRepoUrl,
65	          taskBranch,
66	          baseBranch: taskBaseBranch,
67	          featureId,
68	          taskId,
69	          taskTitle,
70	          githubToken,
71	        });
72	        prUrl = prResult.prUrl;
73	        emit({ type: "impl_pr_opened", task_id: taskId, feature_id: featureId, pr_url: prUrl });
74	      } catch (e) {
75	        emit({ type: "impl_pr_failed", task_id: taskId, details: String(e) });
76	      }
77	    }
78	
79	    const mutateErr = mutateTaskYaml({
80	      workspaceRoot,
81	      featureId,
82	      taskId,
83	      taskBranch,
84	      result,
85	      prUrl,
86	      gitAuthorEmail,
87	      gitAuthorName,
88	      sshKeyPath,
89	    });
90	    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
91	
92	    const logErr = appendLogEntry({
93	      workspaceRoot,
94	      featureId,
95	      taskId,
96	      taskBranch,
97	      entry: {
98	        action: "in_review",
99	        by: gitAuthorEmail,
100	        note: prUrl ? `Implementation PR opened: ${prUrl}` : "Implementation complete.",
101	      },
102	      gitAuthorEmail,
103	      gitAuthorName,
104	      sshKeyPath,
105	    });
106	    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
107	  } else {
108	    const mutateErr = mutateTaskYaml({
109	      workspaceRoot,
110	      featureId,
111	      taskId,
112	      taskBranch,
113	      result,
114	      gitAuthorEmail,
115	      gitAuthorName,
116	      sshKeyPath,
117	    });
118	    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
119	
120	    const logErr = appendLogEntry({
121	      workspaceRoot,
122	      featureId,
