/**
 * Orchestrator side-effect dispatcher.
 *
 * Translates an ExecutorResult into the correct set of side effects:
 *   in_review  → open impl PR, mutate task YAML to in_review, append log
 *   blocked    → mutate task YAML to blocked, append log
 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
 *
 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
 * verify the resulting task state without running the full bootstrap + poll loop.
 */

import type { ExecutorResult } from "@workflow/runtime-abi";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { appendLogEntry } from "./append-log.js";
import { openImplPr } from "./open-pr.js";

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Apply the side effects that correspond to an executor result.
 * Called by the orchestrator polling loop after adapter.run() returns.
 * Non-throwing: individual side-effect errors are emitted as events but do
 * not propagate — the cycle continues normally.
 */
export async function dispatchExecutorResult(
  opts: DispatchExecutorResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    taskTitle,
    taskRepoUrl,
    taskBaseBranch,
    githubToken,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  if (result.terminal_status === "in_review") {
    let prUrl: string | undefined;
    if (githubToken) {
      try {
        const prResult = await openImplPr({
          taskRepoUrl,
          taskBranch,
          baseBranch: taskBaseBranch,
          featureId,
          taskId,
          taskTitle,
          githubToken,
        });
        prUrl = prResult.prUrl;
        emit({ type: "impl_pr_opened", task_id: taskId, feature_id: featureId, pr_url: prUrl });
      } catch (e) {
        emit({ type: "impl_pr_failed", task_id: taskId, details: String(e) });
      }
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "in_review",
        by: gitAuthorEmail,
        note: prUrl ? `Implementation PR opened: ${prUrl}` : "Implementation complete.",
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  } else {
    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "blocked",
        by: gitAuthorEmail,
        note: result.blocked_reason ?? "executor returned non-in_review status",
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  }
}
